	PROCEDURE ANALYZE_TABLE(TABLE_NAME VARCHAR,FIELD_NAME VARCHAR,SAMPLE_RATE INTEGER,HSITOGRAM_NUM INTEGER,AUTO_ADJUST BOOL DEFAULT TRUE,PARALLEL INTEGER DEFAULT 1);
