  PROCEDURE DUMP_TABLE( TABLE_NAME VARCHAR,					--表名
						FILTER VARCHAR,						--where 条件(不写where关键字)
						PATH VARCHAR,						--导出数据 INSERT SQL 的数据库端输出文件(NULL时不输出到文件)
